package geminicli

import (
	"context"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// GenerateText sends a prompt to the Gemini CLI and returns the raw text response.
//
// The prompt is piped to the Gemini CLI via stdin rather than embedded in argv.
// Per gemini --help, the -p/--prompt flag is appended to any input read from
// stdin; we pass a single-space placeholder to trigger headless (non-interactive)
// mode and let stdin carry the actual content, avoiding argv size limits.
func (g *GeminiCLIAgent) GenerateText(ctx context.Context, prompt, model string) (string, error) {
	args := []string{"-p", " "}
	if model != "" {
		args = append(args, "--model", model)
	}
	res, runErr := agent.RunIsolatedTextGeneratorCLIRaw(ctx, g.CommandRunner, "gemini", args, prompt)
	if err := Classifier.Classify(ctx, res, runErr); err != nil {
		return "", err //nolint:wrapcheck // preserve *agent.TextGenError / ctx sentinel for errors.As at the explain layer
	}
	out := strings.TrimSpace(string(res.Stdout))
	if out == "" {
		return "", &agent.TextGenError{
			Kind:     agent.TextGenErrorUnknown,
			Provider: agent.AgentNameGemini,
			Message:  "gemini CLI returned empty output",
		}
	}
	return out, nil
}

package geminicli

import (
	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// Classifier holds the declarative classification data for the Gemini CLI.
// Consumed by agent.Classifier.Classify via geminicli.GenerateText.
//
// Phrase selection is evidence-based: the auth phrases are verbatim from the
// 2026-04-20 research pass (see spec Appendix A). Rate-limit phrases are
// seeded conservatively from common HTTP conventions; the shared HTTP-status
// baseline catches "429"/etc. independently.
var Classifier = &agent.Classifier{
	Provider: agent.AgentNameGemini,
	Phrases: []agent.PhraseRule{
		{Kind: agent.TextGenErrorAuth, Phrase: "Please set an Auth method"},
		{Kind: agent.TextGenErrorAuth, Phrase: "GEMINI_API_KEY"},
		{Kind: agent.TextGenErrorRateLimit, Phrase: "rate limit"},
		{Kind: agent.TextGenErrorRateLimit, Phrase: "quota"},
	},
}

package geminicli

import (
	"context"
	"errors"
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// fixtureGeminiAuthStderr: real stderr from gemini-cli 0.34.0 in the
// 2026-04-20 research pass with no credentials configured. Captured
// verbatim; includes the pre-auth ENOENT noise that prepends the actual
// auth-method guidance on fresh profiles (see spec Risk #2).
const fixtureGeminiAuthStderr = `Failed to save project registry to /tmp/home/.gemini/projects.json: Error: ENOENT: no such file or directory
  errno: -2,
  code: 'ENOENT',
  syscall: 'rename',
  path: '/tmp/home/.gemini/projects.json.tmp',
  dest: '/tmp/home/.gemini/projects.json'
}
Please set an Auth method in your /tmp/home/.gemini/settings.json or specify one of the following environment variables before running: GEMINI_API_KEY, GOOGLE_GENAI_USE_VERTEXAI, GOOGLE_GENAI_USE_GCA`

func TestClassifier_AuthFromCapturedStderr(t *testing.T) {
	t.Parallel()
	res := agent.ExecResult{Stderr: []byte(fixtureGeminiAuthStderr), ExitCode: 41}
	err := Classifier.Classify(context.Background(), res, errors.New("exit 41"))
	var tge *agent.TextGenError
	if !errors.As(err, &tge) {
		t.Fatalf("want *agent.TextGenError; got %v", err)
	}
	if tge.Kind != agent.TextGenErrorAuth {
		t.Errorf("Kind = %q; want auth", tge.Kind)
	}
	if tge.Provider != agent.AgentNameGemini {
		t.Errorf("Provider = %q; want gemini", tge.Provider)
	}
	if !strings.Contains(tge.Message, "Please set an Auth method") {
		t.Errorf("Message does not preserve Gemini's auth guidance: %q", tge.Message)
	}
}

